describe('Search Race Condition Handling', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').as('searchInput');
    cy.get('[data-testid="search-results"]').as('searchResults');
  });

  it('should display only the latest search result when multiple requests are made in quick succession', () => {
    // Type first search term quickly
    cy.get('@searchInput').type('java');
    cy.wait(100);

    // Type second search term before first request completes
    cy.get('@searchInput').clear().type('javascript');
    cy.wait(100);

    // Type third search term before second request completes
    cy.get('@searchInput').clear().type('jest');

    // Wait for results to stabilize
    cy.get('@searchResults').should('be.visible');

    // Verify only the latest search results are displayed
    cy.get('@searchResults').within(() => {
      cy.contains('jest').should('be.visible');
      cy.contains('java').should('not.exist');
      cy.contains('javascript').should('not.exist');
    });

    // Verify result count matches latest query
    cy.get('[data-testid="result-count"]').should('contain', 'Results for: jest');
  });

  it('should handle rapid sequential searches without showing stale data', () => {
    const searchTerms = ['python', 'react', 'node', 'typescript'];

    searchTerms.forEach((term, index) => {
      cy.get('@searchInput').clear().type(term);
      cy.wait(50);
    });

    // Only the last search term should be visible in results
    cy.get('@searchResults').should('be.visible');
    cy.get('[data-testid="search-result-item"]').each(($item) => {
      cy.wrap($item).should('contain', 'typescript');
    });

    // Verify no results from previous searches are present
    cy.get('@searchResults').should('not.contain', 'python');
    cy.get('@searchResults').should('not.contain', 'react');
    cy.get('@searchResults').should('not.contain', 'node');
  });

  it('should cancel previous requests when new search is initiated', () => {
    cy.intercept('GET', '**/api/search*', (req) => {
      req.reply((res) => {
        cy.wait(2000);
        res.send({
          statusCode: 200,
          body: { results: [{ id: 1, title: req.url }] }
        });
      });
    }).as('searchRequest');

    cy.get('@searchInput').type('slow');
    cy.wait(100);

    // Initiate new search before first completes
    cy.get('@searchInput').clear().type('fast');

    // Wait for requests to complete
    cy.wait('@searchRequest');

    // Verify only fast search results are shown
    cy.get('@searchResults').should('contain', 'fast');
  });

  it('should handle empty search after rapid queries', () => {
    cy.get('@searchInput').type('test');
    cy.wait(100);
    cy.get('@searchInput').clear().type('data');
    cy.wait(100);
    cy.get('@searchInput').clear();

    // Results should be cleared or show empty state
    cy.get('@searchResults').should('be.empty');
    cy.get('[data-testid="empty-state"]').should('be.visible');
  });

  it('should maintain correct result order when search completes out of order', () => {
    cy.intercept('GET', '**/api/search?q=slow', (req) => {
      req.reply((res) => {
        cy.wait(1500);
        res.send({
          statusCode: 200,
          body: { results: [{ id: 1, title: 'Slow Result' }] }
        });
      });
    }).as('slowSearch');

    cy.intercept('GET', '**/api/search?q=fast', (req) => {
      req.reply((res) => {
        cy.wait(300);
        res.send({
          statusCode: 200,
          body: { results: [{ id: 2, title: 'Fast Result' }] }
        });
      });
    }).as('fastSearch');

    // Initiate slow search first
    cy.get('@searchInput').type('slow');
    cy.wait(200);

    // Initiate fast search second
    cy.get('@searchInput').clear().type('fast');

    // Even though slow search was initiated first, fast results should display
    cy.get('@searchResults').should('contain', 'Fast Result');
    cy.get('@searchResults').should('not.contain', 'Slow Result');
  });
});
